import { Input } from "./types";

export const inputs = ["/imu"];
export const output = "/gg_g";

// Republish IMU linear acceleration in g (1 g = 9.81 m/s^2) so the
// G-G plot can show lateral/longitudinal load directly in g.
export default function (event: Input<"/imu">): { ax_g: number; ay_g: number } {
  const G = 9.81;
  return {
    ax_g: event.message.linear_acceleration.x / G,
    ay_g: event.message.linear_acceleration.y / G,
  };
}

