import { Input } from "./types";

type Output = { lateral_deviation_m: number };
export const inputs = ["/slam/pose", "/Path"];
export const output = "/path_error";

// Cached path polyline (map frame). Refreshed whenever /Path arrives.
let pathPts: { x: number; y: number }[] = [];

// Signed perpendicular distance from the SLAM pose to the nearest /Path
// segment. Both topics are in the map frame, so a plain 2D projection
// works. Sign: + = car is left of the path direction, - = right.
export default function (
  event: Input<"/slam/pose"> | Input<"/Path">,
): Output | undefined {
  if (event.topic === "/Path") {
    pathPts = event.message.poses.map((p) => ({
      x: p.pose.position.x,
      y: p.pose.position.y,
    }));
    return undefined;
  }
  if (pathPts.length < 2) return undefined;
  const p = event.message.pose.pose.position;
  let bestD = Infinity;
  let bestSigned = 0;
  for (let i = 0; i < pathPts.length - 1; i++) {
    const a = pathPts[i];
    const b = pathPts[i + 1];
    const abx = b.x - a.x, aby = b.y - a.y;
    const apx = p.x - a.x, apy = p.y - a.y;
    const len2 = abx * abx + aby * aby;
    let t = len2 > 0 ? (apx * abx + apy * aby) / len2 : 0;
    t = Math.max(0, Math.min(1, t));
    const dx = apx - t * abx, dy = apy - t * aby;
    const dist = Math.sqrt(dx * dx + dy * dy);
    if (dist < bestD) {
      bestD = dist;
      const cross = abx * apy - aby * apx; // + = left of path direction
      bestSigned = cross >= 0 ? dist : -dist;
    }
  }
  return { lateral_deviation_m: bestSigned };
}

state_labels.sourceCode:
import { Input } from "./types";

type In =
  | Input<"/assi/state"> | Input<"/dv/status"> | Input<"/res/status">
  | Input<"/res/go"> | Input<"/ami/mission"> | Input<"/ctrl/emergency">
  | Input<"/slam/finished"> | Input<"/imu/status">;

type Labels = {
  assi: string; dv: string; res: string; res_go: string;
  ami: string; emergency: string; finished: string; imu: string;
};

export const inputs = ["/assi/state", "/dv/status", "/res/status", "/res/go",
  "/ami/mission", "/ctrl/emergency", "/slam/finished", "/imu/status"];
export const output = "/state_labels";

// Latest raw value of each machine (updated as messages arrive).
const st = { assi: -1, dv: -1, res: -99, res_go: -1, ami: -1,
  emergency: false, finished: false, imu: -1 };

const ASSI = ["OFF", "EMERGENCY", "READY", "DRIVING", "FINISHED"];
const DV = ["IDLE", "PREPARING", "READY", "RUNNING", "FINISHED", "EMERGENCY", "FAILED"];
const AMI = ["Manual", "Acceleration", "Skidpad", "Autocross", "Trackdrive",
  "EVS/EBS", "Inspection", "Shutdown", "Aux1", "Aux2"];

function pick(a: string[], i: number): string {
  return i >= 0 && i < a.length ? a[i] : "?" + i;
}
function resName(s: number): string {
  return s === 0 ? "OK" : s === 1 ? "STOP" : s === 2 ? "GO"
    : s === -1 ? "TIMEOUT" : s === -2 ? "NONE" : "?" + s;
}

export default function (event: In): Labels {
  switch (event.topic) {
    case "/assi/state": st.assi = event.message.data; break;
    case "/dv/status": st.dv = event.message.data; break;
    case "/res/status": st.res = event.message.data; break;
    case "/res/go": st.res_go = event.message.data; break;
    case "/ami/mission": st.ami = event.message.data; break;
    case "/ctrl/emergency": st.emergency = event.message.data; break;
    case "/slam/finished": st.finished = event.message.data; break;
    case "/imu/status": st.imu = event.message.data; break;
  }
  return {
    assi: pick(ASSI, st.assi),
    dv: pick(DV, st.dv),
    res: resName(st.res),
    res_go: st.res_go === 1 ? "GO" : st.res_go === 0 ? "no go" : "?" + st.res_go,
    ami: pick(AMI, st.ami),
    emergency: st.emergency ? "EBS REQUESTED" : "nominal",
    finished: st.finished ? "FINISHED" : "running",
    imu: st.imu === 0 ? "OK" : "fault (" + st.imu + ")",
  };
}
